func newProfile() unsafe.Pointer { return unsafe.Pointer(new(modeprofile.Profile)) }

func newNProfile(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]modeprofile.Profile, n)))
}

func ptrProfile(p unsafe.Pointer, c int32) any {
	r := (*modeprofile.Profile)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Name
	case 4:
		return &r.Code
	case 5:
		return &r.Description
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return (*string)(unsafe.Pointer(&r.ServiceModel))
	case 8:
		return (*string)(unsafe.Pointer(&r.EquipmentClass))
	case 9:
		return (*string)(unsafe.Pointer(&r.ExecutionParty))
	case 10:
		return &r.Capabilities
	case 11:
		return &r.IsOrgDefault
	case 12:
		return &r.Priority
	case 13:
		return &r.SpecificityScore
	case 14:
		return (**string)(unsafe.Pointer(&r.CustomerID))
	case 15:
		return &r.ShipmentTypeIDs
	case 16:
		return &r.ServiceTypeIDs
	case 17:
		return &r.EquipmentTypeIDs
	case 18:
		return &r.EffectiveStartDate
	case 19:
		return &r.EffectiveEndDate
	case 20:
		return &r.Version
	case 21:
		return &r.CreatedAt
	case 22:
		return &r.UpdatedAt
	case 23:
		return &r.SearchVector
	case 24:
		return &r.Rank
	}
	return nil
}

func valueProfile(p unsafe.Pointer, c int32) any {
	r := (*modeprofile.Profile)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Name
	case 4:
		return r.Code
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return string(r.Status)
	case 7:
		return string(r.ServiceModel)
	case 8:
		return string(r.EquipmentClass)
	case 9:
		return string(r.ExecutionParty)
	case 10:
		if r.Capabilities == nil {
			return nil
		}
		return r.Capabilities
	case 11:
		return r.IsOrgDefault
	case 12:
		return r.Priority
	case 13:
		return r.SpecificityScore
	case 14:
		if r.CustomerID == nil {
			return nil
		}
		return string(*r.CustomerID)
	case 15:
		if r.ShipmentTypeIDs == nil {
			return nil
		}
		return r.ShipmentTypeIDs
	case 16:
		if r.ServiceTypeIDs == nil {
			return nil
		}
		return r.ServiceTypeIDs
	case 17:
		if r.EquipmentTypeIDs == nil {
			return nil
		}
		return r.EquipmentTypeIDs
	case 18:
		if r.EffectiveStartDate == nil {
			return nil
		}
		return *r.EffectiveStartDate
	case 19:
		if r.EffectiveEndDate == nil {
			return nil
		}
		return *r.EffectiveEndDate
	case 20:
		return r.Version
	case 21:
		return r.CreatedAt
	case 22:
		return r.UpdatedAt
	case 23:
		return r.SearchVector
	case 24:
		return r.Rank
	}
	return nil
}

func attachProfile(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*modeprofile.Profile)(p)
	switch rel {
	case 0:
		r.Rules = append(r.Rules, (*modeprofile.CapabilityRule)(child))
	}
}

func beforeCreateProfile(ctx context.Context, p unsafe.Pointer) error {
	return (*modeprofile.Profile)(p).BeforeCreate(ctx)
}

func beforeUpdateProfile(ctx context.Context, p unsafe.Pointer) error {
	return (*modeprofile.Profile)(p).BeforeUpdate(ctx)
}

func beforeSaveProfile(ctx context.Context, p unsafe.Pointer) error {
	return (*modeprofile.Profile)(p).BeforeSave(ctx)
}

func init() {
	capabilityRulesTable.Relations[0].Target = ProfilesSchema()
	deviationsTable.Relations[0].Target = ProfilesSchema()
	deviationsTable.Relations[1].Target = tenantdb.UsersSchema()
	profilesTable.Relations[0].Target = CapabilityRulesSchema()
}

